_WORKBENCH_CONTEXT_KEYS: frozenset[str] = frozenset({"workbench", "secrets"})
_WORKBENCH_SECRET_KEYS: frozenset[str] = frozenset(
    {
        "WORKBENCH_KNOWLEDGE_CAPABILITY",
        "WORKBENCH_CANVAS_CAPABILITY",
    }
)
_WORKBENCH_REQUESTED_ARTIFACT_KINDS: frozenset[str] = frozenset(
    {"prd", "prototype", "image", "code", "document", "data"}
)
_WORKBENCH_SCOPE_KEYS: frozenset[str] = frozenset(
    {
        "runId",
        "runtimeAttemptId",
        "requestedArtifactKinds",
        "knowledgeEnabled",
        "canvasTools",
        "prototypePatchBaselines",
    }
)


def _is_trusted_internal_caller(request: Request | None) -> bool:
    user = getattr(getattr(request, "state", None), "user", None)
    return (getattr(user, "system_role", None) == INTERNAL_SYSTEM_ROLE
            and getattr(getattr(request, "state", None), "auth_source", None) == AUTH_SOURCE_INTERNAL)


def _strip_workbench_channels(value: Any) -> Any:
    if not isinstance(value, Mapping):
        return value
    sanitized = dict(value)
    for key in (*_WORKBENCH_CONTEXT_KEYS, *_WORKBENCH_SECRET_KEYS):
        sanitized.pop(key, None)
    return sanitized


def _sanitize_run_config(request_config: dict[str, Any] | None) -> dict[str, Any] | None:
    """Remove reserved Workbench channels before config persistence or execution."""
    if request_config is None:
        return None
    sanitized = dict(request_config)
    sanitized.pop("recursion_limit", None)
    for container_name in ("configurable", "context"):
        if container_name in sanitized:
            sanitized[container_name] = _strip_workbench_channels(sanitized[container_name])
    for key in (*_WORKBENCH_CONTEXT_KEYS, *_WORKBENCH_SECRET_KEYS):
        sanitized.pop(key, None)
    return sanitized


def _normalize_workbench_scope(value: Any) -> dict[str, Any] | None:
    if not isinstance(value, Mapping):
        return None
    if not set(value).issubset(_WORKBENCH_SCOPE_KEYS):
        return None
    run_id = value.get("runId")
    runtime_attempt_id = value.get("runtimeAttemptId")
    requested_artifact_kinds = value.get("requestedArtifactKinds")
    knowledge_enabled = value.get("knowledgeEnabled")
    if (
        not isinstance(run_id, str)
        or not run_id
        or not isinstance(runtime_attempt_id, str)
        or not runtime_attempt_id
        or (knowledge_enabled is not None and knowledge_enabled is not True)
        or (
            requested_artifact_kinds is not None
            and (
                not isinstance(requested_artifact_kinds, list)
                or len(requested_artifact_kinds) > len(_WORKBENCH_REQUESTED_ARTIFACT_KINDS)
                or any(
                    not isinstance(kind, str)
                    or kind not in _WORKBENCH_REQUESTED_ARTIFACT_KINDS
                    for kind in requested_artifact_kinds
                )
                or len(set(requested_artifact_kinds)) != len(requested_artifact_kinds)
            )
        )
    ):
        return None
    return {key: value[key] for key in _WORKBENCH_SCOPE_KEYS if key in value}


def _normalize_workbench_secrets(value: Any) -> dict[str, str]:
    if not isinstance(value, Mapping):
        return {}
    return {
        key: secret
        for key, secret in value.items()
        if key in _WORKBENCH_SECRET_KEYS and isinstance(secret, str) and secret
    }


_DEFAULT_LEAD_GRAPH_RECURSION_LIMIT = 100
_WORKBENCH_PRD_LEAD_GRAPH_RECURSION_LIMIT = 200
_WORKBENCH_LINKED_LEAD_GRAPH_RECURSION_LIMIT = 400


def _apply_workbench_lead_recursion_limit(
    config: dict[str, Any],
    *,
    trusted_internal_caller: bool,
) -> None:
    normalized_scope = None
    runtime_context = config.get("context")
    if trusted_internal_caller is True and isinstance(runtime_context, Mapping):
        normalized_scope = _normalize_workbench_scope(runtime_context.get("workbench"))
    requested_kinds = (
        normalized_scope.get("requestedArtifactKinds")
        if normalized_scope is not None
        else None
    )
    # Each tool round traverses multiple middleware nodes. Linked delivery must
    # complete both staged artifacts while keeping the graph budget bounded.
    if requested_kinds is not None and set(requested_kinds) == {"prd", "prototype"}:
        config["recursion_limit"] = _WORKBENCH_LINKED_LEAD_GRAPH_RECURSION_LIMIT
    elif requested_kinds == ["prd"]:
        config["recursion_limit"] = _WORKBENCH_PRD_LEAD_GRAPH_RECURSION_LIMIT
    else:
        config["recursion_limit"] = _DEFAULT_LEAD_GRAPH_RECURSION_LIMIT

if "user_id" in context and isinstance(runtime_context, dict):
    runtime_context.setdefault("user_id", context["user_id"])
if allow_workbench_context and isinstance(runtime_context, dict):
    scope = _normalize_workbench_scope(context.get("workbench"))
    if scope is None:
        return
    secrets = _normalize_workbench_secrets(context.get("secrets"))
    if scope.get("knowledgeEnabled") is True:
        if "WORKBENCH_KNOWLEDGE_CAPABILITY" not in secrets:
            scope = dict(scope)
            scope.pop("knowledgeEnabled", None)
    else:
        secrets.pop("WORKBENCH_KNOWLEDGE_CAPABILITY", None)
    runtime_context["workbench"] = scope
    if secrets:
        runtime_context["secrets"] = secrets

_WORKBENCH_RUN_HISTORY_METADATA_KEYS: frozenset[str] = frozenset(
    {
        "run_id",
        "workbench_run_id",
        "workbench_runtime_attempt_id",
        "workbench_provider_idempotency_key",
        "workbench_attempt",
    }
)
_WORKBENCH_RUN_HISTORY_METADATA_VALUE_MAX_LENGTH = 128


class ThreadHistoryRequest(BaseModel):
    """Request body for checkpoint history."""

    limit: int = Field(default=10, ge=1, le=100, description="Maximum entries")
    before: str | None = Field(default=None, description="Cursor for pagination")
    metadata: dict[str, Any] = Field(default_factory=dict, description="Checkpoint metadata filter")

    @field_validator("metadata")
    @classmethod
    def _validate_workbench_run_filter(cls, value: dict[str, Any]) -> dict[str, Any]:
        if not value:
            return value
        if set(value) != _WORKBENCH_RUN_HISTORY_METADATA_KEYS:
            raise ValueError("History metadata filter must contain exactly the Workbench Run binding keys")
        for key in _WORKBENCH_RUN_HISTORY_METADATA_KEYS:
            candidate = value[key]
            if key == "workbench_attempt":
                if not isinstance(candidate, int) or isinstance(candidate, bool) or candidate < 1:
                    raise ValueError("History metadata attempt must be a positive integer")
                continue
            if key == "workbench_provider_idempotency_key":
                if (
                    not isinstance(candidate, str)
                    or len(candidate) != 69
                    or not candidate.startswith("wbrt:")
                    or any(character not in "0123456789abcdef" for character in candidate[5:])
                ):
                    raise ValueError("History provider idempotency key must use the Workbench format")
                continue
            if (
                not isinstance(candidate, str)
                or not candidate
                or len(candidate) > _WORKBENCH_RUN_HISTORY_METADATA_VALUE_MAX_LENGTH
                or candidate.strip() != candidate
                or any(
                    not character.isascii()
                    or not (character.isalnum() or character in "-_")
                    for character in candidate
                )
            ):
                raise ValueError("History metadata filter values must be bounded identifiers")
        return value
